WITH scored AS (SELECT id, customer_id, amount, shipping_fee, CORR(amount, discount) OVER w_hist AS corr_amount_discount, SUM(amount) OVER (PARTITION BY customer_id ORDER BY discount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount FROM orders WHERE channel IN ('partner', 'web', 'store') WINDOW w_hist AS (PARTITION BY status)) SELECT id, customer_id, amount, corr_amount_discount FROM scored ORDER BY customer_id;
